"""The real crew behind the control plane's activities (Stage 5's ``Crew`` port).

``OmegaCrew.handle`` dispatches each activity to its role: Sentinel (``route_hit``), Pathologist
(``triage``, ``reproduce``), Archivist (``attribute``), governor and Coordinator
(``plan_budget``, ``hypothesize``, ``coordinate``, ``dispute_experiment``, ``budget_exhausted``),
Surgeons (``surgeon`` through Stage 5's ``SurgeonStep``), the Auditor (``audit_gates``), the
shipper (``ship``) and the L4 re-verification (``rebase_and_rerun``). Ledger-shaped steps
(``record_transition``, ``park``, ``escalate``, ``ledger_append``) append to a hash-chained
ledger file (``kintsugi.proof.ledger`` format) until Stage 8 moves it to the ``ledger`` branch.

Stage 7 owns antibodies, motifs, vaccination and quarantine: those steps answer honestly that
nothing exists yet (no antibody match, an empty motif scan, a placeholder antibody reference
recorded as pending). The canary is real: each batch runs the host's tasks on the merged code
under the background chaos profile.

Workers load it through ``kintsugi.crew.runtime`` (configured per deployment or rehearsal).
"""

from __future__ import annotations

import json
import threading
from collections.abc import Callable, Mapping
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from kintsugi.control import contracts as c
from kintsugi.control.activities import StepContext
from kintsugi.control.surgeon_step import AttemptLog, SessionRunner, SurgeonStep
from kintsugi.crew.archivist import Archivist
from kintsugi.crew.auditor import Auditor
from kintsugi.crew.context import CrewContext
from kintsugi.crew.coordinator import Coordinator
from kintsugi.crew.pathologist import Pathologist
from kintsugi.crew.sentinel import Sentinel
from kintsugi.gates.checkout import clean_checkout
from kintsugi.gates.evals import run_tasks
from kintsugi.memory.graph import GraphError
from kintsugi.proof.ledger import Ledger, genesis_hash
from kintsugi.sandbox import worktree
from kintsugi.senses.drift import reverify_plan
from kintsugi.senses.fixes_mcp import Fixes, FixesUnavailable

CANARY_TASKS = 10


class FileLedger:
    """The hash-chained ledger in a JSONL file, appended under a process lock."""

    def __init__(self, path: Path, genesis: str) -> None:
        self.path = Path(path)
        self.genesis = genesis
        self._lock = threading.Lock()

    def append(self, entry: Mapping[str, Any]) -> str:
        with self._lock:
            text = self.path.read_text(encoding="utf-8") if self.path.is_file() else ""
            ledger = Ledger.from_jsonl(text, self.genesis)
            record = ledger.append(
                {"at": datetime.now(UTC).isoformat(timespec="seconds"), **dict(entry)}
            )
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self.path.write_text(ledger.to_jsonl(), encoding="utf-8", newline="\n")
            return str(record["hash"])

    def entries(self) -> tuple[dict[str, Any], ...]:
        text = self.path.read_text(encoding="utf-8") if self.path.is_file() else ""
        return Ledger.from_jsonl(text, self.genesis).entries


class Shipper:
    """``ship`` (``kintsugi.control.ship``): issue → PR with the receipt → G7 → merge."""

    def ship(self, out: c.SurgeonOutcome) -> c.Shipment:  # pragma: no cover - protocol
        raise NotImplementedError


class OmegaCrew:
    def __init__(
        self,
        ctx: CrewContext,
        *,
        runner: Callable[[], SessionRunner],
        shipper: Shipper | None = None,
        fixes: Fixes | None = None,
        tags: Any = None,  # kintsugi.senses.tags.TagWriter for neatlogs traces
        ledger: FileLedger | None = None,
    ) -> None:
        self.ctx = ctx
        self.runner = runner
        self.shipper = shipper
        self.fixes = fixes
        self.tags = tags
        self.ledger = ledger or FileLedger(
            ctx.state / "ledger.jsonl", genesis_hash("rehearsal", b"\0" * 32)
        )
        self.auditor = Auditor(ctx)
        self.coordinator = Coordinator(ctx)

    def handle(self, ctx: StepContext, *args: Any) -> Any:
        handler = getattr(self, f"do_{ctx.name}", None)
        if handler is None:
            raise NotImplementedError(f"the crew has no {ctx.name} step")
        return handler(ctx, *args)

    # ---- senses and diagnosis ------------------------------------------------------------------

    def do_route_hit(self, step: StepContext, hit: c.Hit, open_incidents: list[str]) -> Any:
        return Sentinel(self.ctx).route(hit, open_incidents)

    def do_triage(self, step: StepContext, alert: c.Alert) -> c.Signature:
        return Pathologist(self.ctx).triage(alert)

    def do_tag_traces(self, step: StepContext, incident: str, ids: list[str], phase: str) -> int:
        real = [t for t in ids if not t.startswith("local:")]
        if self.tags is None or not real:
            return 0
        for trace in real:
            self.tags.apply(trace, add=[f"incident:{incident}", f"phase:{phase}"])
        return len(real)

    def do_match_antibody(self, step: StepContext, sig: c.Signature) -> None:
        return None  # the antibody library is Stage 7: every incident is a primary response

    def do_reproduce(self, step: StepContext, sig: c.Signature) -> c.Repro:
        return Pathologist(self.ctx).reproduce(sig)

    def do_attribute(self, step: StepContext, sig: c.Signature, repro: c.Repro) -> c.Cause:
        return Archivist(self.ctx).attribute(sig, repro)

    def do_fixes_prior(self, step: StepContext, sig: c.Signature) -> str | None:
        if self.fixes is None:
            return None
        try:
            suggestions = self.fixes.triage_list(trace_ids=list(sig.trace_ids)[:20])
            if not suggestions:
                return None
            found = self.fixes.triage_get_investigation(str(suggestions[0]["id"]))
        except FixesUnavailable:
            return None
        return json.dumps(found)[:2000]

    # ---- planning and decisions -----------------------------------------------------------------

    def do_plan_budget(self, step: StepContext, sig: c.Signature, cause: c.Cause) -> Any:
        return self.coordinator.plan_budget(sig, cause)

    def do_hypothesize(self, step: StepContext, *args: Any) -> list[c.Card]:
        return self.coordinator.hypothesize(*args)

    def do_coordinate(self, step: StepContext, *args: Any) -> c.Decision:
        return self.coordinator.coordinate(*args)

    def do_dispute_experiment(self, step: StepContext, incident: str, d: c.Decision) -> Any:
        return self.coordinator.dispute_experiment(incident, d)

    def do_budget_exhausted(self, step: StepContext, *args: Any) -> bool:
        return self.coordinator.budget_exhausted(*args)

    # ---- repair -------------------------------------------------------------------------------

    def do_surgeon(self, step: StepContext, card: c.Card) -> c.SurgeonOutcome:
        brief = json.loads(card.brief)
        target = self.ctx.target(str(brief["host"]))
        case = self.ctx.case(card.incident_id)
        plan = case.reader("governor").get("plan", "plan", None) or {}
        budget = float(plan.get("budget_usd", 0.0))
        if plan and case.spent() >= budget:  # G6: a round never starts past the budget
            case.put(
                "refusal",
                card.hypothesis,
                {"reason": f"budget spent: ${case.spent():.2f} of ${budget:.2f} (G6)"},
                by="surgeon",
            )
            return c.SurgeonOutcome(
                card.incident_id,
                card.hypothesis,
                step.attempt,
                worktree.branch_name(card.incident_id, card.hypothesis),
                "",
                None,
            )
        attempts = AttemptLog(self.ctx.state / "attempts.sqlite")
        return SurgeonStep(target.repo, attempts, self.runner()).run(card, step)

    def do_audit_gates(self, step: StepContext, out: c.SurgeonOutcome) -> c.GateVerdict:
        return self.auditor.audit(out)

    def do_rewind(self, step: StepContext, outs: list[c.SurgeonOutcome]) -> None:
        """Discard the worktrees, keep each attempt's commit (and checkpoint) as evidence."""
        for out in outs:
            host = self._host(out)
            try:
                wt = worktree.open_existing(
                    self.ctx.target(host).repo, out.incident_id, out.hypothesis
                )
            except worktree.WorktreeError:
                continue  # already rewound (a retried step)
            kept = worktree.discard(wt)
            self.ledger.append(
                {
                    "type": "rewind",
                    "incident": out.incident_id,
                    "hypothesis": out.hypothesis,
                    "pinned": kept.pinned_ref,
                    "head": kept.head,
                }
            )

    def do_rebase_and_rerun(
        self, step: StepContext, outs: list[c.SurgeonOutcome], repo: str, new_main: str
    ) -> None:
        """L4: record, per candidate, what the move of main forces the gates to re-check."""
        for out in outs:
            if out.commit_sha is None:
                continue
            case = self.ctx.case(out.incident_id)
            card = case.reader("auditor").get("card", out.hypothesis)
            target = self.ctx.target(str(card["host"]))
            previous = case.reader("auditor").get("verdict", out.hypothesis, None) or {}
            try:
                plan = reverify_plan(target.repo, str(card["base_sha"]), new_main, out.commit_sha)
                record: dict[str, Any] = {
                    **plan.record(),
                    "rerun_g4": plan.rerun_g4,
                    "intersection": list(plan.intersection),
                    "changed": list(plan.changed),
                    "patched": list(plan.patched),
                    "tests": list(plan.tests),
                }
            except (GraphError, OSError) as error:  # no graph here: re-run everything
                record = {
                    "G1": "rerun",
                    "G2": "rerun",
                    "G3": "rerun:all",
                    "G4": "rerun:graph-unavailable",
                    "G7": "final-head",
                    "rerun_g4": True,
                    "graph_error": str(error)[:300],
                }
            record.update(
                {
                    "repo": repo,
                    "old_main": card["base_sha"],
                    "new_main": new_main,
                    "g4": previous.get("g4") or {},
                }
            )
            case.put("reverify", out.hypothesis, record, by="auditor")
            self.ledger.append(
                {
                    "type": "reverify",
                    "incident": out.incident_id,
                    "hypothesis": out.hypothesis,
                    "record": {k: v for k, v in record.items() if k.startswith("G")},
                }
            )

    def do_ship(self, step: StepContext, out: c.SurgeonOutcome) -> c.Shipment:
        if self.shipper is None:
            return c.Shipment(out.incident_id, out.hypothesis, out.branch, None, False, False)
        return self.shipper.ship(out)

    def do_canary_sample(self, step: StepContext, shipment: c.Shipment, batch: int) -> list[bool]:
        """One live-traffic batch on the merged code: which tasks failed."""
        import importlib

        host = self.ctx.incidents.host_of(shipment.incident_id) or self._host_of_case(shipment)
        target = self.ctx.target(host)
        target.make_importable()
        pool = importlib.import_module(f"{target.host.package}.evals.generate").tasks("train")
        start = (batch * CANARY_TASKS) % max(1, len(pool))
        tasks = (pool[start:] + pool[:start])[:CANARY_TASKS]
        sha = shipment.merge_sha or shipment.branch
        with clean_checkout(target.repo, sha) as checkout:
            runs = run_tasks(target, checkout, tasks, seed=5000 + batch, phase="canary").runs
        return [not run.passed for run in runs]

    # ---- ledger-shaped steps -----------------------------------------------------------------

    def do_record_transition(self, step: StepContext, record: c.TransitionRecord) -> None:
        self.ledger.append(
            {"type": "transition", "incident": record.incident_id, "transition": _plain(record)}
        )

    def do_park(self, step: StepContext, sig: c.Signature, reason: str) -> None:
        self.ledger.append({"type": "park", "incident": sig.incident_id, "reason": reason})

    def do_escalate(self, step: StepContext, incident: str, reason: str) -> None:
        case = self.ctx.case(incident)
        view = case.reader("coordinator")
        dossier = {name: view.get("decision", name) for name in view.names("decision")}
        self.ledger.append(
            {
                "type": "escalate",
                "incident": incident,
                "reason": reason,
                "decisions": dossier,
                "spent_usd": case.spent(),
            }
        )

    def do_ledger_append(self, step: StepContext, entry: dict[str, Any]) -> str:
        return self.ledger.append(entry)

    # ---- Stage 7 (antibodies, canary actions, vaccination) --------------------------------------

    def do_revert(self, step: StepContext, shipment: c.Shipment) -> bool:
        return False  # the revert path (L3) is Stage 7

    def do_quarantine_related(self, step: StepContext, shipment: c.Shipment) -> int:
        return 0

    def do_synthesize_antibody(
        self, step: StepContext, out: c.SurgeonOutcome, cause: c.Cause
    ) -> c.AntibodyRef:
        ref = c.AntibodyRef(f"AB-{out.incident_id}", "0.0")
        self.ledger.append(
            {
                "type": "antibody",
                "incident": out.incident_id,
                "antibody": f"{ref.antibody_id}@{ref.version}",
                "state": "pending-stage-7",
            }
        )
        return ref

    def do_motif_scan(self, step: StepContext, ab: c.AntibodyRef) -> list[str]:
        return []

    def do_apply_antibody(self, step: StepContext, ab: c.AntibodyRef, host: str) -> Any:
        return c.VaccinationResult(ab.antibody_id, host, False, "vaccination is Stage 7")

    def do_backfill_receptor(self, step: StepContext, ab: c.AntibodyRef) -> None:
        return None

    def do_fixes_resolve(self, step: StepContext, sig: c.Signature, shipment: c.Shipment) -> None:
        return None

    # ---- helpers ------------------------------------------------------------------------------

    def _host(self, out: c.SurgeonOutcome) -> str:
        card = self.ctx.case(out.incident_id).reader("auditor").get("card", out.hypothesis)
        return str(card["host"])

    def _host_of_case(self, shipment: c.Shipment) -> str:
        card = (
            self.ctx.case(shipment.incident_id).reader("auditor").get("card", shipment.hypothesis)
        )
        return str(card["host"])


def _plain(value: Any) -> dict[str, Any]:
    from kintsugi.crew.casefile import plain

    return dict(plain(value))

# --------------------------------------------------------------------------- FleetSupervisor


@dataclass
class SupervisorState:
    """What a FleetSupervisor run hands to the next one at ``continue_as_new``."""

    open: dict[str, str] = field(default_factory=dict)  # incident → host
    waiting: list[c.Alert] = field(default_factory=list)  # held back by the per-host limit
    pending: list[c.Hit] = field(default_factory=list)  # signalled, not yet routed
    seen: list[str] = field(default_factory=list)  # recent hit keys (bounded)
    budgets: dict[str, float] = field(default_factory=dict)
    paused_antibodies: list[str] = field(default_factory=list)
    closed: dict[str, str] = field(default_factory=dict)  # incident → terminal state
    events: int = 0  # across runs
    runs: int = 1
    operator_paused: str | None = None


@workflow.defn
class FleetSupervisor:
    def __init__(self) -> None:
        self.s = SupervisorState()
        self.config = c.ControlConfig()
        self.run_events = 0
        self.drifts: list[tuple[str, str]] = []

    # signals (§5.3.3) -------------------------------------------------------------------
    @workflow.signal
    def hit(self, hit: c.Hit) -> None:
        self.s.pending.append(hit)

    @workflow.signal
    def drift(self, repo: str, new_main: str) -> None:
        self.drifts.append((repo, new_main))

    @workflow.signal
    def budget_update(self, host: str, pool_usd: float) -> None:
        self.s.budgets[host] = pool_usd

    @workflow.signal
    def pause_antibody(self, antibody_id: str) -> None:
        if antibody_id not in self.s.paused_antibodies:
            self.s.paused_antibodies.append(antibody_id)

    @workflow.signal
    def operator_pause(self, reason: str) -> None:
        self.s.operator_paused = reason

    @workflow.signal
    def operator_resume(self) -> None:
        self.s.operator_paused = None

    @workflow.signal
    def incident_closed(self, incident_id: str, state: str) -> None:
        self.s.open.pop(incident_id, None)
        self.s.closed[incident_id] = state

    # queries ----------------------------------------------------------------------------
    @workflow.query
    def status(self) -> dict[str, Any]:
        return {"open": len(self.s.open), "waiting": len(self.s.waiting),
                "pending": len(self.s.pending), "events": self.s.events, "runs": self.s.runs,
                "closed": dict(self.s.closed), "operator_paused": self.s.operator_paused,
                "paused_antibodies": list(self.s.paused_antibodies)}  # fmt: skip

    @workflow.query
    def open_incidents(self) -> dict[str, str]:
        return dict(self.s.open)

    @workflow.query
    def budget(self, host: str) -> float | None:
        return self.s.budgets.get(host)

    # run --------------------------------------------------------------------------------
    @workflow.run
    async def run(self, config: c.ControlConfig, state: SupervisorState | None = None) -> None:
        self.config = config
        if state is not None:
            self.s = state
            self.s.runs += 1
        while True:
            await workflow.wait_condition(self._has_work)
            while self.drifts:
                repo, new_main = self.drifts.pop(0)
                for incident_id in list(self.s.open):
                    child = workflow.get_external_workflow_handle(incident_id)
                    await child.signal("drift_signal", args=[repo, new_main])
            if self.s.operator_paused is None:
                await self._start_waiting(config)
                while self.s.pending and self.s.operator_paused is None:
                    await self._route(self.s.pending.pop(0), config)
                    self.s.events += 1
                    self.run_events += 1
                    if self.run_events >= config.continue_as_new_every:
                        await workflow.wait_condition(workflow.all_handlers_finished)
                        workflow.continue_as_new(args=[config, self.s])

    def _host_open(self, host: str) -> int:
        return sum(1 for h in self.s.open.values() if h == host)

    def _has_work(self) -> bool:
        if self.drifts:
            return True
        if self.s.operator_paused is not None:
            return False
        limit = self.config.max_open_per_host
        return bool(self.s.pending) or any(self._host_open(a.host) < limit for a in self.s.waiting)

    async def _start_waiting(self, config: c.ControlConfig) -> None:
        still: list[c.Alert] = []
        for alert in self.s.waiting:
            if self._host_open(alert.host) < config.max_open_per_host:
                await self._start(alert, config)
            else:
                still.append(alert)
        self.s.waiting = still

    async def _route(self, hit: c.Hit, config: c.ControlConfig) -> None:
        if hit.hit_key in self.s.seen:
            return
        self.s.seen.append(hit.hit_key)
        del self.s.seen[:-SEEN_HIT_MEMORY]
        decision = await act("route_hit", hit, list(self.s.open), config=config,
                             result_type=c.RouteDecision)  # fmt: skip
        if decision.action == "attach" and decision.incident_id in self.s.open:
            child = workflow.get_external_workflow_handle(decision.incident_id)
            await child.signal("attach", hit)
        elif decision.action == "open" and decision.incident_id:
            if decision.incident_id in self.s.open or decision.incident_id in self.s.closed:
                return
            alert = c.Alert(decision.incident_id, hit.host or "unknown", (hit,),
                            decision.severity, config.supervisor_id)  # fmt: skip
            if self._host_open(alert.host) < config.max_open_per_host:
                await self._start(alert, config)
            else:
                self.s.waiting.append(alert)

    async def _start(self, alert: c.Alert, config: c.ControlConfig) -> None:
        await workflow.start_child_workflow(
            Incident.run,
            args=[alert, config],
            id=alert.incident_id,
            task_queue=CREW,
            parent_close_policy=ParentClosePolicy.ABANDON,
            retry_policy=RetryPolicy(maximum_attempts=1),
        )
        self.s.open[alert.incident_id] = alert.host


WORKFLOWS = (FleetSupervisor, Incident, Canary, CrossHostMaturation, VaccinationWave, Onboarding,
             SabotageCampaign, AuditAnchor)  # fmt: skip

        self.root = Path(root) / incident
        self.root.mkdir(parents=True, exist_ok=True)

    # ---- raw storage (orchestrator only) ---------------------------------------------------

    def _path(self, kind: str, name: str) -> Path:
        if kind not in KINDS:
            raise KeyError(f"unknown case-file artifact kind {kind!r}")
        safe = "".join(ch if ch.isalnum() or ch in "-_.@" else "_" for ch in name)
        return self.root / kind / f"{safe}.json"

    def put(self, kind: str, name: str, data: Any, *, by: str) -> Path:
        column = KINDS.get(kind)
        if column is None or column not in WRITES.get(by, frozenset()):
            raise InformationFlowViolation(f"{by} may not write {kind}")
        path = self._path(kind, name)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(f".{os.getpid()}.{threading.get_ident()}.tmp")
        tmp.write_text(json.dumps(plain(data), indent=1, sort_keys=True, ensure_ascii=False)
                       + "\n", encoding="utf-8", newline="\n")  # fmt: skip
        os.replace(tmp, path)
        self._append("access.jsonl", {"op": "write", "role": by, "kind": kind, "name": name})
        return path

    def exists(self, kind: str, name: str) -> bool:
        return self._path(kind, name).is_file()

    def tool_read(self, kind: str, name: str, *, tool: str) -> Any:
        """Deterministic tooling (the bisect runner, the gate runner) loads the G0 cassette and
        repro record to *execute* them; nothing it reads enters a model's context. Limited to
        trace and summary artifacts, and logged."""
        if KINDS.get(kind) not in ("traces", "summary"):
            raise InformationFlowViolation(f"tool {tool} may not load {kind}")
        if not self.exists(kind, name):
            return None
        self._append("access.jsonl", {"op": "tool", "role": tool, "kind": kind, "name": name})
        return self._load(kind, name)

    def _load(self, kind: str, name: str) -> Any:
        return json.loads(self._path(kind, name).read_text(encoding="utf-8"))

    def names(self, kind: str) -> list[str]:
        folder = self.root / kind
        return sorted(p.stem for p in folder.glob("*.json")) if folder.is_dir() else []

    # ---- role views --------------------------------------------------------------------------

    def reader(self, role: str) -> CaseView:
        if role not in READS:
            raise KeyError(f"unknown role {role!r}")
        return CaseView(self, role)

    # ---- append-only logs ----------------------------------------------------------------------

    def _append(self, log: str, record: Mapping[str, Any]) -> None:
        line = json.dumps({"at": round(time.time(), 3), **plain(dict(record))},
                          sort_keys=True, ensure_ascii=False) + "\n"  # fmt: skip
        with _APPEND_LOCK, open(self.root / log, "a", encoding="utf-8", newline="\n") as handle:
            handle.write(line)

    def _read_log(self, log: str) -> Iterator[dict[str, Any]]:
        path = self.root / log
        if not path.is_file():
            return
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                yield json.loads(line)

    def add_cost(self, role: str, usd: float, what: str) -> None:
        self._append("costs.jsonl", {"role": role, "usd": round(float(usd), 6), "what": what})

    def spent(self) -> float:
        return round(sum(float(r["usd"]) for r in self._read_log("costs.jsonl")), 6)

    def costs_by_role(self) -> dict[str, float]:
        totals: dict[str, float] = {}
        for record in self._read_log("costs.jsonl"):
            totals[record["role"]] = round(totals.get(record["role"], 0.0) + record["usd"], 6)
        return totals

    def log_call(self, record: Mapping[str, Any]) -> None:
        """One crew model call: role, template and prompt hashes, manifest, model, cost, reply."""
        self._append("calls.jsonl", record)

    def calls(self) -> list[dict[str, Any]]:
        return list(self._read_log("calls.jsonl"))

    def accesses(self) -> list[dict[str, Any]]:
        return list(self._read_log("access.jsonl"))


class CaseView:
    """One role's window on a case file: reads outside its matrix row raise and nothing leaks."""

    def __init__(self, case: CaseFile, role: str) -> None:
        self.case = case
        self.role = role

    def _allowed(self, kind: str) -> None:
        column = KINDS.get(kind)
        if column is None:
            raise KeyError(f"unknown case-file artifact kind {kind!r}")
        if column not in READS[self.role]:
            self.case._append("access.jsonl", {"op": "denied", "role": self.role, "kind": kind})
            raise InformationFlowViolation(f"{self.role} may not read {kind} ({column})")

    def get(self, kind: str, name: str, default: Any = _MISSING) -> Any:
        self._allowed(kind)
        if not self.case.exists(kind, name):
            if default is _MISSING:
                raise FileNotFoundError(f"{self.case.incident}: no {kind}/{name}")
            return default
        self.case._append("access.jsonl", {"op": "read", "role": self.role, "kind": kind,
                                           "name": name})  # fmt: skip
        return self.case._load(kind, name)

    def names(self, kind: str) -> list[str]:
        self._allowed(kind)
        return self.case.names(kind)
"""One crew model call, end to end: template → manifest → model → validation → case file.

``consult`` is the only way a role asks a model anything, so every call is rendered from a
pinned template, carries its context manifest (§5.14), is metered into the incident's cost log
(G6) and is recorded in ``calls.jsonl`` with its template and prompt hashes. That log is also
what the I5 leak scan reads: no holdout canary may ever appear in a crew prompt or reply.

When no model is configured (offline runs, unit tests) or the model fails, a role's
deterministic fallback answers instead, and the call record says so.
"""

from __future__ import annotations

from collections.abc import Callable, Mapping
from dataclasses import dataclass
from typing import Any

from kintsugi.crew import templates
from kintsugi.crew.casefile import CaseFile
from kintsugi.crew.llm import Model, ModelCall, ModelError, ModelReply
from kintsugi.crew.manifest import ContextBuilder, ContextManifest

DETERMINISTIC = "deterministic"


@dataclass(frozen=True)
class Consultation:
    data: Any
    provider: str
    model: str | None
    cost_usd: float
    manifest: ContextManifest
    error: str | None = None


def consult(
    model: Model | None,
    case: CaseFile,
    builder: ContextBuilder,
    template: str,
    *,
    schema: Mapping[str, Any] | None,
    fallback: Callable[[], Any] | None = None,
    max_budget_usd: float = 1.0,
    model_id: str | None = None,
) -> Consultation:
    role = builder.manifest.role
    rendered = templates.render(template, **builder.values)
    manifest = builder.manifest
    manifest.template, manifest.template_sha = template, rendered.template_sha
    manifest.prompt_sha = rendered.prompt_sha
    reply: ModelReply | None = None
    error: str | None = None
    if model is not None:
        call = ModelCall(role, template, rendered.system, rendered.prompt, schema, model_id,
                         max_budget_usd)  # fmt: skip
        try:
            reply = model.complete(call)
        except ModelError as failure:
            if fallback is None:
                _log(case, role, rendered, manifest, None, None, str(failure))
                raise
            error = str(failure)
    if reply is not None:
        data, provider, used, cost = reply.data, reply.provider, reply.model, reply.cost_usd
    elif fallback is not None:
        data, provider, used, cost = fallback(), DETERMINISTIC, None, 0.0
    else:
        raise ModelError(f"{role}/{template}: no model configured and no deterministic fallback")
    _log(case, role, rendered, manifest, reply, data, error)
    if cost:
        case.add_cost(role, cost, f"{template} via {provider}")
    return Consultation(data, provider, used, cost, manifest, error)


def _log(
    case: CaseFile,
    role: str,
    rendered: templates.Rendered,
    manifest: ContextManifest,
    reply: ModelReply | None,
    data: Any,
    error: str | None,
) -> None:
    case.log_call({
        "role": role,
        "template": rendered.template,
        "template_sha": rendered.template_sha,
        "prompt_sha": rendered.prompt_sha,
        "prompt": rendered.prompt,
        "manifest": manifest.as_dict(),
        "provider": reply.provider if reply else DETERMINISTIC,
        "model": reply.model if reply else None,
        "session": reply.session_id if reply else None,
        "cost_usd": reply.cost_usd if reply else 0.0,
        "reply": reply.text if reply else None,
        "data": data,
        "error": error,
    })  # fmt: skip
"""Hashed prompt templates for the crew (spec §4.5.4, §5.14; amendment A-17).

Every crew prompt is generated from incident data by a template, never written by hand at run
time. A template is one file in ``kintsugi/crew/prompts/<name>.md``: a system part, a line
``---- user ----``, then the user part. Placeholders are ``$name`` (:class:`string.Template`).

- The **template hash** is the SHA-256 of the file's bytes. ``prompts/SHA256SUMS`` pins every
  template, and a test fails when a template changes without its pin, so a prompt change is
  always a visible, reviewed diff.
- The **prompt hash** is the SHA-256 of the exact rendered user prompt. For a Surgeon it is the
  ``Kintsugi-Prompt`` trailer and the attestation's ``prompt_template_sha`` (A-17); for the other
  roles it is recorded with the call in the incident's case file.

Rendering is strict: a missing or an unknown field raises, so no prompt ships with a literal
``$placeholder`` in it or silently drops incident data.
"""

from __future__ import annotations

import hashlib
import string
from dataclasses import dataclass
from functools import cache
from pathlib import Path

PROMPTS = Path(__file__).with_name("prompts")
PINS = PROMPTS / "SHA256SUMS"
SEPARATOR = "\n---- user ----\n"


class TemplateError(ValueError):
    pass


def sha256_text(text: str) -> str:
    return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class Template:
    name: str
    system: str
    user: str
    sha256: str  # "sha256:<hex>" of the template file's bytes

    @property
    def fields(self) -> frozenset[str]:
        found: set[str] = set()
        for part in (self.system, self.user):
            found.update(string.Template(part).get_identifiers())
        return frozenset(found)


@dataclass(frozen=True)
class Rendered:
    template: str
    template_sha: str
    system: str
    prompt: str

    @property
    def prompt_sha(self) -> str:
        return sha256_text(self.prompt)


def names() -> list[str]:
    return sorted(path.stem for path in PROMPTS.glob("*.md"))


@cache
def load(name: str) -> Template:
    path = PROMPTS / f"{name}.md"
    if not path.is_file():
        raise TemplateError(f"no prompt template {name!r}")
    raw = path.read_bytes()
    text = raw.decode("utf-8")
    if SEPARATOR not in text:
        raise TemplateError(f"{path.name}: missing the '---- user ----' separator")
    system, user = text.split(SEPARATOR, 1)
    return Template(name, system.strip(), user.strip() + "\n",
                    "sha256:" + hashlib.sha256(raw).hexdigest())  # fmt: skip


def render(name: str, **values: object) -> Rendered:
    """Fill every placeholder of ``name`` exactly once; values are converted with ``str``."""
    template = load(name)
    given = set(values)
    missing, unknown = template.fields - given, given - template.fields
    if missing or unknown:
        raise TemplateError(f"{name}: missing {sorted(missing)}, unknown {sorted(unknown)}")
    text = {key: str(value) for key, value in values.items()}
    try:
        system = string.Template(template.system).substitute(text)
        prompt = string.Template(template.user).substitute(text)
    except (KeyError, ValueError) as error:  # a stray "$" in the template itself
        raise TemplateError(f"{name}: {error}") from None
    return Rendered(name, template.sha256, system, prompt)


def pins() -> dict[str, str]:
    """``prompts/SHA256SUMS``: ``<hex>  <name>.md`` per line."""
    pinned: dict[str, str] = {}
    for line in PINS.read_text(encoding="utf-8").splitlines():
        if line.strip() and not line.startswith("#"):
            digest, _, filename = line.partition("  ")
            pinned[filename.strip().removesuffix(".md")] = "sha256:" + digest.strip()
    return pinned


def check_pins() -> list[str]:
    """Templates whose bytes differ from their pin, and pins without a template."""
    pinned = pins()
    problems = [f"{name}: not pinned" for name in names() if name not in pinned]
    problems += [f"{name}: pinned but missing" for name in pinned if name not in names()]
    problems += [f"{name}: hash changed (re-pin after review)" for name in names()
                 if name in pinned and pinned[name] != load(name).sha256]  # fmt: skip
    return problems


def pin_file() -> str:
    """The text ``prompts/SHA256SUMS`` should hold for the templates on disk."""
    header = "# KINTSUGI-Omega crew prompt templates (spec 4.5.4): sha256 of each template file.\n"
    lines = [f"{load(n).sha256.removeprefix('sha256:')}  {n}.md" for n in names()]
    return header + "\n".join(lines) + "\n"
