"""Motif predicates on real code, and a host's code graph (spec §4.4.3; plan §2c).

``kintsugi.memory.motif`` matches structure; this module decides what the structure's nodes
*are*, on the host's own source:

- ``is_retry_wrapper``: the name and decorator heuristics nominate a function; its source
  confirms it (a loop whose ``try`` body calls one of the function's parameters, i.e. it
  re-runs a callable it was given). A named-like-retry function that does not loop is not one.
- ``has_mutable_accumulator``: the deterministic ``ast`` scan of the class; an inconclusive scan
  goes to the classifier (``claude-haiku-5-5`` through the Immunologist), whose verdict is cached
  by (symbol, source SHA-256) so the same class is never asked twice.
- ``is_side_effecting``: the host's tool registry (``side_effect: true``) reached by ``CALLS*``.

A host's graph comes from **one** ``entire graph snapshot`` of its repository, restricted to the
host's package files (the monorepo holds every host, and fixtures that must never match), with
the side-effecting tools of its ``host.yaml`` marked and function and class sources attached.
"""

from __future__ import annotations

import ast
import hashlib
import json
import textwrap
import threading
from collections.abc import Callable, Iterable, Mapping
from pathlib import Path
from typing import Any

import networkx as nx

from kintsugi.memory import motif
from kintsugi.memory.graph import Snapshot
from kintsugi.memory.motif import Predicate, Verdict

# (predicate, qualified name, source) → a verdict, or None when no classifier can decide.
Classifier = Callable[[str, str, str], bool | None]
_LOOPS = (ast.For, ast.While, ast.AsyncFor)


# ---- retry wrappers -------------------------------------------------------------------------


def scan_retry_wrapper(source: str, name: str) -> Verdict:
    """Does function ``name`` re-run a callable parameter inside a loop with a ``try``?"""
    try:
        tree = ast.parse(textwrap.dedent(source))
    except SyntaxError:
        return Verdict.INCONCLUSIVE
    fn = next(
        (
            n
            for n in ast.walk(tree)
            if isinstance(n, ast.FunctionDef | ast.AsyncFunctionDef) and n.name == name
        ),
        None,
    )
    if fn is None:
        return Verdict.INCONCLUSIVE
    params = {a.arg for a in (*fn.args.posonlyargs, *fn.args.args, *fn.args.kwonlyargs)}
    if fn.args.vararg:
        params.add(fn.args.vararg.arg)
    for loop in (n for n in ast.walk(fn) if isinstance(n, _LOOPS)):
        for handler in (n for n in ast.walk(loop) if isinstance(n, ast.Try)):
            for call in (n for stmt in handler.body for n in ast.walk(stmt)):
                if (
                    isinstance(call, ast.Call)
                    and isinstance(call.func, ast.Name)
                    and call.func.id in params
                ):
                    return Verdict.TRUE
    return Verdict.FALSE


# ---- the classifier cache -------------------------------------------------------------------


class VerdictCache:
    """Classifier verdicts keyed by (predicate, symbol, source SHA-256), persisted as JSON."""

    def __init__(self, path: Path | None = None) -> None:
        self.path = path
        self._lock = threading.Lock()
        self.data: dict[str, bool] = {}
        if path is not None and path.is_file():
            self.data = {k: bool(v) for k, v in json.loads(path.read_text("utf-8")).items()}

    @staticmethod
    def key(predicate: str, name: str, source: str) -> str:
        digest = hashlib.sha256(source.encode("utf-8")).hexdigest()[:16]
        return f"{predicate}|{name}|{digest}"

    def get(self, predicate: str, name: str, source: str) -> bool | None:
        return self.data.get(self.key(predicate, name, source))

    def put(self, predicate: str, name: str, source: str, verdict: bool) -> None:
        with self._lock:
            self.data[self.key(predicate, name, source)] = verdict
            if self.path is not None:
                self.path.parent.mkdir(parents=True, exist_ok=True)
                text = json.dumps(self.data, indent=1, sort_keys=True) + "\n"
                self.path.write_text(text, encoding="utf-8", newline="\n")


def registry(
    *, classify: Classifier | None = None, cache: VerdictCache | None = None
) -> dict[str, Predicate]:
    """The predicates a motif may name, confirmed on source where the graph carries it."""
    verdicts = cache or VerdictCache()

    def decide(predicate: str, graph: nx.DiGraph, node: str, scan: Verdict) -> bool:
        if scan is not Verdict.INCONCLUSIVE:
            return scan is Verdict.TRUE
        data = graph.nodes[node]
        source = data.get("source")
        if not isinstance(source, str) or classify is None:
            return False
        name = str(data.get("qualified_name") or data.get("name"))
        cached = verdicts.get(predicate, name, source)
        if cached is not None:
            return cached
        answer = classify(predicate, name, source)
        if answer is None:
            return False
        verdicts.put(predicate, name, source, answer)
        return answer

    def retry_wrapper(graph: nx.DiGraph, node: str) -> bool:
        if not motif.is_retry_wrapper(graph, node):
            return False
        source = graph.nodes[node].get("source")
        if not isinstance(source, str):
            return True  # no source in the graph (fixtures): the heuristics decide
        name = str(graph.nodes[node].get("name", ""))
        return decide("is_retry_wrapper", graph, node, scan_retry_wrapper(source, name))

    def accumulator(graph: nx.DiGraph, node: str) -> bool:
        data = graph.nodes[node]
        recorded = data.get("mutable_accumulator")
        if isinstance(recorded, bool):
            return recorded
        source = data.get("source")
        if not isinstance(source, str):
            return False
        scan = motif.scan_mutable_accumulator(source, str(data.get("name", "")))
        return decide("has_mutable_accumulator", graph, node, scan)

    return {
        "is_retry_wrapper": retry_wrapper,
        "has_mutable_accumulator": accumulator,
        "is_side_effecting": motif.is_side_effecting,
    }


# ---- a host's graph -------------------------------------------------------------------------


def restrict(snapshot: Snapshot, prefixes: Iterable[str]) -> Snapshot:
    """The part of a repository snapshot under ``prefixes`` (POSIX paths, relative)."""
    roots = tuple(p.rstrip("/") + "/" if p not in ("", ".") else "" for p in prefixes)
    keep = {s["id"] for s in snapshot.symbols if str(s["file_path"]).startswith(roots)}
    return Snapshot(
        snapshot.header,
        [f for f in snapshot.files if str(f.get("path", "")).startswith(roots)],
        snapshot.externals,
        [s for s in snapshot.symbols if s["id"] in keep],
        [r for r in snapshot.relations if r["from_id"] in keep and r["to_id"] in keep],
        snapshot.summary,
    )


def host_graph(
    snapshot: Snapshot,
    *,
    package_dir: str,
    side_effect_tools: Iterable[str],
    source_root: Path,
) -> nx.DiGraph:
    """The motif engine's graph of one host: its package only, tools marked, sources attached.

    ``side_effect_tools`` are tool names from the host's registry; a function of the package
    with that name is the tool (hosts define each tool as a function of the same name)."""
    part = restrict(snapshot, [package_dir])
    writers = set(side_effect_tools)
    tools = {s["qualified_name"] for s in part.symbols if s["name"] in writers}
    cache: dict[str, list[str]] = {}

    def attrs(record: Mapping[str, Any]) -> Mapping[str, Any]:
        if record["kind"] not in ("function", "method", "class"):
            return {}
        path = source_root / str(record["file_path"])
        if not path.is_file():
            return {}
        lines = cache.setdefault(str(path), path.read_text(encoding="utf-8").splitlines())
        start, end = int(record["start_line"]), int(record["end_line"])
        return {"source": textwrap.dedent("\n".join(lines[start - 1 : end]))}

    return part.to_code_graph(attrs=attrs, side_effect_tools=tools)


def names(graph: nx.DiGraph, embedding: Mapping[str, str]) -> dict[str, str]:
    """An embedding as {motif node: qualified name}."""
    return {k: str(graph.nodes[v].get("qualified_name") or v) for k, v in embedding.items()}

"""The Antibody Library (spec §5.8): memory B cells, in the monorepo's ``antibodies/`` (D3).

Layout (§5.8.1)::

    antibodies/
      index.json             signature φ → AB-id@version; per antibody its state and description
      AB-1/
        antibody.yaml        the spec (Appendix E.1), current version
        receptor.json        the neatlogs Detection body as drafted (and created, when it is)
        motif.yaml           the motif (§4.4.3)
        recipe.md            the Claude Code instruction template ({intent} and {scope} slots)
        contract.yaml        gate thresholds
        evidence.json        incident, traces, checkpoints, statistics, CI and PR links
        lineage.json         versions, state changes, quarantines, refinements, hosts protected
        versions/1.0.yaml    every version's antibody.yaml, so ``AB-1@1.0`` stays resolvable

Retrieval (§5.8.3): an exact φ match first; then a deterministic semantic fallback over the
signature's fields (error class, failing span, tool, preceding 3-gram) accepted at θ = 0.85;
then the caller confirms structurally (motif on the host's graph, preconditions) and requires
``state = ACTIVE``. Anything else is a primary response.

The library is written by the Immunologist's activities (tool-written files, A-1); every state
change is a lineage event, so the proof bundle can replay how an antibody got where it is.
"""

from __future__ import annotations

import json
import re
import threading
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

import yaml

from kintsugi.memory.antibody import Antibody, AntibodyState, AntibodyVersion

THETA = 0.85
_FIELD_WEIGHTS = {"error_class": 0.4, "failing_span": 0.2, "tool": 0.2, "preceding": 0.2}
_lock = threading.Lock()


class LibraryError(RuntimeError):
    pass


def _dump_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(data, indent=1, sort_keys=True, ensure_ascii=False) + "\n"
    path.write_text(text, encoding="utf-8", newline="\n")


def _dump_yaml(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    text = yaml.safe_dump(data, sort_keys=False, allow_unicode=True)
    path.write_text(text, encoding="utf-8", newline="\n")


def _now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds")


def similarity(a: Mapping[str, Any], b: Mapping[str, Any]) -> float:
    """Deterministic semantic similarity of two signatures' fields, in [0, 1]."""
    score = 0.0
    for name, weight in _FIELD_WEIGHTS.items():
        left, right = a.get(name), b.get(name)
        if name == "preceding":
            x, y = set(left or []), set(right or [])
            score += weight * (len(x & y) / len(x | y) if x | y else 1.0)
        elif left is not None and left == right:
            score += weight
    return round(score, 4)


@dataclass(frozen=True)
class Retrieval:
    antibody: Antibody
    how: str  # "exact" | "semantic"
    similarity: float


class AntibodyLibrary:
    def __init__(self, root: Path) -> None:
        self.root = Path(root)

    # ---- reading ------------------------------------------------------------------------------

    def ids(self) -> list[str]:
        if not self.root.is_dir():
            return []
        found = [p.name for p in self.root.iterdir() if (p / "antibody.yaml").is_file()]
        return sorted(found, key=lambda i: int(i.split("-")[1]))

    def next_id(self) -> str:
        numbers = [int(i.split("-")[1]) for i in self.ids()]
        return f"AB-{max(numbers, default=0) + 1}"

    def load(self, ab_id: str, version: str | None = None) -> Antibody:
        folder = self.root / ab_id
        path = folder / "antibody.yaml"
        if version is not None:
            path = folder / "versions" / f"{AntibodyVersion.parse(version)}.yaml"
        if not path.is_file():
            raise LibraryError(f"no antibody {ab_id}" + (f"@{version}" if version else ""))
        return Antibody.from_yaml(path.read_text(encoding="utf-8"))

    def ref(self, ref: str) -> Antibody:
        """``AB-1@1.0`` (pinned) or ``AB-1`` (current)."""
        ab_id, _, version = ref.partition("@")
        return self.load(ab_id, version or None)

    def index(self) -> dict[str, Any]:
        path = self.root / "index.json"
        if not path.is_file():
            return {"signatures": {}, "antibodies": {}}
        return json.loads(path.read_text(encoding="utf-8"))

    def lineage(self, ab_id: str) -> dict[str, Any]:
        path = self.root / ab_id / "lineage.json"
        return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}

    def evidence(self, ab_id: str) -> dict[str, Any]:
        path = self.root / ab_id / "evidence.json"
        return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}

    def receptor_body(self, ab_id: str) -> dict[str, Any]:
        path = self.root / ab_id / "receptor.json"
        return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}

    def recipe(self, ab_id: str) -> str:
        return (self.root / ab_id / "recipe.md").read_text(encoding="utf-8")

    def active(self) -> list[Antibody]:
        return [ab for i in self.ids() if (ab := self.load(i)).state is AntibodyState.ACTIVE]

    # ---- retrieval (§5.8.3 steps 1–2) -----------------------------------------------------------

    def retrieve(
        self, phi: str, fields: Mapping[str, Any], *, theta: float = THETA
    ) -> Retrieval | None:
        """The antibody whose signature matches φ exactly, or semantically at ≥ θ.

        Only ACTIVE antibodies are returned: a CANDIDATE is unproven and a QUARANTINED one must
        not be applied (its receptor stays on, its recipe does not)."""
        exact = self.index()["signatures"].get(phi)
        if exact is not None:
            ab = self.ref(str(exact).split("@")[0])
            if ab.state is AntibodyState.ACTIVE:
                return Retrieval(ab, "exact", 1.0)
        best: Retrieval | None = None
        for ab in self.active():
            score = similarity(fields, ab.signature.fields)
            if score >= theta and (best is None or score > best.similarity):
                best = Retrieval(ab, "semantic", score)
        return best

    # ---- writing -------------------------------------------------------------------------------

    def save(
        self,
        ab: Antibody,
        *,
        receptor_body: Mapping[str, Any] | None = None,
        evidence: Mapping[str, Any] | None = None,
        description: str | None = None,
        event: Mapping[str, Any] | None = None,
    ) -> Path:
        """Write ``ab`` (all seven files, the version snapshot, the index) and log ``event``."""
        with _lock:
            folder = self.root / ab.id
            data = ab.model_dump(mode="json")
            _dump_yaml(folder / "antibody.yaml", data)
            _dump_yaml(folder / "versions" / f"{ab.version}.yaml", data)
            _dump_yaml(folder / "motif.yaml", {"motif": ab.motif.model_dump(mode="json")})
            _dump_yaml(folder / "contract.yaml", ab.contract.model_dump(mode="json"))
            (folder / "recipe.md").write_text(ab.recipe.rstrip() + "\n", encoding="utf-8",
                                              newline="\n")  # fmt: skip
            if receptor_body is not None:
                _dump_json(folder / "receptor.json", dict(receptor_body))
            if evidence is not None:
                _dump_json(folder / "evidence.json", {**self.evidence(ab.id), **dict(evidence)})
            lineage = self.lineage(ab.id) or {"id": ab.id, "events": []}
            lineage.update(ab.lineage.model_dump(mode="json"))
            if event is not None:
                lineage["events"].append({"at": _now(), "version": ab.version, **dict(event)})
            _dump_json(folder / "lineage.json", lineage)
            index = self.index()
            index["signatures"][ab.signature.hash] = ab.ref
            entry = index["antibodies"].get(ab.id, {})
            entry.update({"version": ab.version, "state": str(ab.state)})
            if description is not None:
                entry["description"] = description
            index["antibodies"][ab.id] = entry
            _dump_json(self.root / "index.json", index)
            return folder

    def transition(self, ab_id: str, to: AntibodyState, *, why: str, **detail: Any) -> Antibody:
        """A lifecycle move (§5.8.2), logged; QUARANTINED counts a quarantine."""
        current = self.load(ab_id)
        if current.state is to:
            return current
        moved = current.transition(to)
        self.save(moved, event={"event": "state", "from": str(current.state), "to": str(to),
                                "why": why, **detail})  # fmt: skip
        return moved

    def record(self, ab_id: str, event: Mapping[str, Any]) -> None:
        """Append a lineage event without changing the antibody (backfill, PR comments, …)."""
        with _lock:
            path = self.root / ab_id / "lineage.json"
            lineage = self.lineage(ab_id) or {"id": ab_id, "events": []}
            lineage["events"].append({"at": _now(), "version": self.load(ab_id).version,
                                      **dict(event)})  # fmt: skip
            _dump_json(path, lineage)

    def protect(self, ab_id: str, host: str) -> Antibody:
        """``host`` now carries this antibody (maturation or vaccination merged or PR-opened)."""
        ab = self.load(ab_id)
        if host in ab.lineage.hosts_protected:
            return ab
        hosts = sorted({*ab.lineage.hosts_protected, host})
        updated = ab.model_copy(update={"lineage": ab.lineage.model_copy(
            update={"hosts_protected": hosts})})  # fmt: skip
        self.save(updated, event={"event": "protected", "host": host})
        return updated

    def unprotect(self, ab_id: str, host: str, *, why: str) -> Antibody:
        ab = self.load(ab_id)
        hosts = [h for h in ab.lineage.hosts_protected if h != host]
        updated = ab.model_copy(update={"lineage": ab.lineage.model_copy(
            update={"hosts_protected": hosts})})  # fmt: skip
        self.save(updated, event={"event": "unprotected", "host": host, "why": why})
        return updated


_SLUG = re.compile(r"[^a-z0-9]+")


def cassette_slug(text: str) -> str:
    """A file-name-safe slug, e.g. for a trace-to-test cassette."""
    return _SLUG.sub("_", text.lower()).strip("_")[:60] or "case"

