"""Syncing a batch of contacts to the CRM, each exactly once, with its region.

``sync_contacts`` looks each contact's region up through ``enrich`` (a geo API that may
rate-limit) and creates it through ``create_contact``. A 429 re-runs the attempt; the
``SyncSession`` records which contacts were created and where to resume.
"""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from typing import Any

from practice_crm.retry import RateLimited, retry_with_backoff
from practice_crm.tools import create_contact, enrich


@dataclass(frozen=True)
class Contact:
    key: str
    name: str
    domain: str


@dataclass(frozen=True)
class Batch:
    ref: str
    contacts: tuple[Contact, ...]


def build_batch(payload: dict[str, Any]) -> Batch:
    ref = payload["ref"]
    contacts = tuple(
        Contact(f"{ref}#{n}", item["name"], item["domain"])
        for n, item in enumerate(payload["contacts"], 1)
    )
    return Batch(ref, contacts)


class SyncSession:
    """Which contacts of one batch are created, and where to resume."""

    def __init__(self, batch: Batch) -> None:
        self.batch = batch
        self.created: set[str] = set()
        self.cursor = 0

    @property
    def done(self) -> bool:
        return self.cursor >= len(self.batch.contacts)

    def pending(self) -> tuple[Contact, ...]:
        return self.batch.contacts[self.cursor :]

    def push(self, contact: Contact, region: str) -> None:
        if contact.key not in self.created:
            create_contact({"key": contact.key, "ref": self.batch.ref, "name": contact.name,
                            "region": region})  # fmt: skip
            self.created.add(contact.key)
        self.cursor += 1


def sync_contacts(batch: Batch, session: SyncSession | None = None) -> SyncSession:
    """Create every pending contact of ``batch``; a rate limit retries the attempt."""

    def attempt() -> SyncSession:
        current = session or SyncSession(batch)
        for contact in current.pending():
            current.push(contact, enrich(contact.domain))
        return current

    return retry_with_backoff(attempt)


def sync_worker(
    batches: Iterable[Batch], sessions: dict[str, SyncSession] | None = None
) -> dict[str, SyncSession]:
    """Sync a queue of batches; a batch still rate-limited after its retries keeps its session
    and is resumed on the next pass."""
    sessions = {} if sessions is None else sessions
    for batch in batches:
        session = sessions.setdefault(batch.ref, SyncSession(batch))
        if session.done:
            continue
        try:
            sync_contacts(batch, session)
        except RateLimited:
            continue
    return sessions

"""The CRM practice host's tools: a geo enrichment lookup and the CRM API (``create_contact``)."""

from __future__ import annotations

from typing import Any

from neatlogs import span

from hostkit import external
from practice_crm.retry import RateLimited


class GeoUnavailable(RuntimeError):
    reason_code = "GEO_UNAVAILABLE"


class CrmError(RuntimeError):
    reason_code = "CRM_ERROR"


@span(kind="TOOL", name="enrich")
def enrich(domain: str) -> str:
    """The sales region of a company domain."""
    response = external.call("geo", "GET", "/region", params={"domain": domain})
    if response.status_code == 429:
        raise RateLimited(f"enrich {domain}: HTTP 429")
    if response.status_code >= 400:
        raise GeoUnavailable(f"enrich {domain}: HTTP {response.status_code}")
    return str(response.json()["region"])


@span(kind="TOOL", name="create_contact")
def create_contact(contact: dict[str, Any]) -> None:
    """Create one CRM contact. The CRM API has no idempotency: creating twice makes two."""
    response = external.call("crm", "POST", "/contacts", json=contact)
    if response.status_code >= 400:
        raise CrmError(f"create_contact {contact.get('key')}: HTTP {response.status_code}")


@span(kind="TOOL", name="list_contacts")
def list_contacts(ref: str) -> list[dict[str, Any]]:
    response = external.call("crm", "GET", "/contacts", params={"ref": ref})
    if response.status_code >= 400:
        raise CrmError(f"list_contacts {ref}: HTTP {response.status_code}")
    return list(response.json()["contacts"])

"""Retry with exponential backoff for rate-limited external calls."""

from __future__ import annotations

import time
from collections.abc import Callable


class RateLimited(Exception):
    """An external service answered HTTP 429."""

    reason_code = "RATE_LIMITED"


def retry_with_backoff[T](
    fn: Callable[[], T], attempts: int = 5, base_delay: float = 0.02, max_delay: float = 0.5
) -> T:
    """Call ``fn`` until it returns, re-running it whole after each ``RateLimited``."""
    for attempt in range(attempts):
        try:
            return fn()
        except RateLimited:
            if attempt == attempts - 1:
                raise
            time.sleep(min(max_delay, base_delay * 2**attempt))
    raise AssertionError("unreachable")

"""A deterministic geo API: ``GET /region?domain=acme.example`` → ``{"region": "EMEA"}``."""

from __future__ import annotations

import hashlib
import time
from collections.abc import Mapping
from typing import Any

REGIONS = ("AMER-East", "AMER-West", "EMEA", "APAC", "LATAM")
SERVICE_TIME_S = 0.006


def region(domain: str) -> str:
    digest = hashlib.sha256(domain.lower().encode("utf-8")).digest()
    return REGIONS[digest[0] % len(REGIONS)]


def handle(method: str, path: str, query: Mapping[str, str], body: bytes) -> tuple[int, Any]:
    time.sleep(SERVICE_TIME_S)
    if method != "GET" or path != "/region":
        return 404, {"error": "not found"}
    domain = query.get("domain", "")
    if "." not in domain:
        return 400, {"error": f"bad domain {domain!r}"}
    return 200, {"domain": domain, "region": region(domain)}

"""A CRM API, one CRM per task: ``POST /contacts`` creates (no idempotency) and
``GET /contacts?ref=…`` lists a batch's contacts."""

from __future__ import annotations

import json
import threading
import time
from collections.abc import Mapping
from typing import Any

SERVICE_TIME_S = 0.010
_crm: dict[str, list[dict[str, Any]]] = {}
_lock = threading.Lock()


def reset() -> None:
    with _lock:
        _crm.clear()


def handle(
    method: str, path: str, query: Mapping[str, str], body: bytes, namespace: str = ""
) -> tuple[int, Any]:
    time.sleep(SERVICE_TIME_S)
    with _lock:
        contacts = _crm.setdefault(namespace, [])
        if method == "POST" and path == "/contacts":
            contact = json.loads(body or b"{}")
            if not isinstance(contact, dict) or "key" not in contact:
                return 400, {"error": "a contact needs a key"}
            contacts.append(dict(contact))
            return 201, {"created": contact["key"]}
        if method == "GET" and path == "/contacts":
            ref = query.get("ref")
            listed = [dict(c) for c in contacts if ref is None or c.get("ref") == ref]
            return 200, {"contacts": listed}
    return 404, {"error": "not found"}

"""Task generator: batches of 3 to 6 contacts at company domains, with their gold records.

The train split is generated from a public seed; the holdout is generated once from a secret
seed by KINTSUGI-Omega's holdout custody and sealed (``generate("holdout", seed, n, canary=…)``).
"""

from __future__ import annotations

import random
from typing import Any

from practice_crm.services.geo_api import region

SIZES = {"train": 60, "holdout": 40}
TRAIN_SEED = 20261012
FIRST = ("Ada", "Grace", "Alan", "Edsger", "Barbara", "Donald", "Frances", "Ken", "Radia", "Tim")
LAST = ("Lovelace", "Hopper", "Turing", "Dijkstra", "Liskov", "Knuth", "Allen", "Thompson")
COMPANIES = ("acme", "globex", "initech", "umbrella", "hooli", "vandelay", "soylent", "tyrell",
             "wonka", "stark", "wayne", "cyberdyne")  # fmt: skip
TLDS = ("example", "test", "invalid")


def _batch(rng: random.Random, ref: str) -> dict[str, Any]:
    contacts = [
        {"name": f"{rng.choice(FIRST)} {rng.choice(LAST)}",
         "domain": f"{rng.choice(COMPANIES)}.{rng.choice(TLDS)}"}
        for _ in range(rng.randint(3, 6))
    ]  # fmt: skip
    return {"ref": ref, "contacts": contacts}


def gold(batch: dict[str, Any]) -> list[dict[str, Any]]:
    return [
        {"key": f"{batch['ref']}#{n}", "name": c["name"], "region": region(c["domain"])}
        for n, c in enumerate(batch["contacts"], 1)
    ]


def generate(split: str, seed: int, n: int, *, canary: str | None = None) -> list[dict[str, Any]]:
    rng = random.Random(f"{split}:{seed}")
    prefix = "CT" if split == "train" else "CH"
    tasks = []
    for i in range(n):
        batch = _batch(rng, f"{prefix}-{i + 1:03d}")
        task: dict[str, Any] = {"id": batch["ref"], "batch": batch,
                                "gold": {"contacts": gold(batch)}}  # fmt: skip
        if canary is not None:
            task["batch"]["note"] = f"ref {canary}"
        tasks.append(task)
    return tasks


def tasks(split: str) -> list[dict[str, Any]]:
    if split != "train":
        raise ValueError("only the train split is public; the holdout is sealed")
    return generate("train", TRAIN_SEED, SIZES["train"])

